<?= $this->section('scripts') ?><script>
$(function(){const f=$('#notificationSettingsForm');f.on('submit',function(e){e.preventDefault();f.find('.validation-error').empty();ajaxRequest({url:'<?= base_url('admin/configuration/settings/notification-settings/save') ?>',data:f.serialize(),success:function(r){if(r.status){showSuccess(r.msg);setTimeout(function(){location.reload();},600);}else{showError(r.msg);if(r.errors)Object.keys(r.errors).forEach(function(k){f.find('[data-error-for="'+k+'"]').text(r.errors[k]);});}}});});});
